const menu=document.querySelector('.menu');
const links=document.querySelector('.nav-links');
menu?.addEventListener('click',()=>{const open=links.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Close':'Menu'});
document.querySelectorAll('.nav-links a').forEach(a=>a.addEventListener('click',()=>{links.classList.remove('open');menu?.setAttribute('aria-expanded','false');if(menu)menu.textContent='Menu'}));
document.getElementById('year').textContent=new Date().getFullYear();

const assessment={
  accounting:{match:'Ongoing outsourced accounting',situationTitle:'What best describes your monthly accounting needs?',situationContext:'This helps determine the recurring workload and level of monthly support.',situations:[['I want to outsource the full accounting function','Full-service monthly accounting','General ledger, reconciliations, AP/AR oversight, close, and reporting.'],['I need help completing month-end close','Month-end close support','The books are maintained internally, but closing and review need support.'],['My current provider or staff cannot keep up','Capacity or service gap','Deadlines, reconciliations, or reporting are slipping.'],['I am replacing an existing accounting provider','Changing providers','I need an orderly transition with continuity and documentation.']],scopeTitle:'Define the monthly accounting workload.',scopeContext:'Estimate the recurring transaction, account, entity, and reporting volume.',fields:[['select','Monthly transactions','monthly_transactions',['Under 100','100–300','301–750','More than 750','Not sure']],['select','Bank and credit-card accounts','financial_accounts',['1–3','4–7','8–15','More than 15','Not sure']],['select','Entities or company files','entities',['1','2–3','4–10','More than 10']],['select','Desired monthly close timing','close_timing',['Within 5 business days','Within 10 business days','Within 15 business days','Flexible / not sure']],['select','Payroll included in the accounting workflow?','payroll_included',['No','Yes — one state','Yes — multiple states','Not sure']]],result:['Monthly Outsourced Accounting','Your answers indicate a recurring accounting engagement should be scoped around transaction volume, account reconciliations, entity count, close timing, and reporting needs.']},
  cleanup:{match:'Accounting cleanup or catch-up',situationTitle:'What is driving the cleanup or catch-up project?',situationContext:'Choose the issue that best represents the current condition of the records.',situations:[['The books are months or years behind','Books are behind','Transactions, reconciliations, or monthly closes have not been completed.'],['Account balances cannot be trusted','Balances are unreliable','Bank, credit card, loan, payroll, or balance-sheet accounts do not reconcile.'],['A filing, audit, loan, or deadline is approaching','A deadline is approaching','Reliable records are needed for an external requirement.'],['I inherited a disorganized accounting file','Historical records need reconstruction','Prior entries, mappings, and supporting documentation need review.']],scopeTitle:'Define the cleanup and reconstruction scope.',scopeContext:'Estimate the historical period, account count, payroll impact, and deadline.',fields:[['select','Period requiring cleanup','cleanup_period',['1–3 months','4–6 months','7–12 months','1–2 years','More than 2 years']],['select','Bank, credit-card, loan, and merchant accounts','cleanup_accounts',['1–3','4–7','8–15','More than 15','Not sure']],['select','Payroll periods affected?','cleanup_payroll',['No','Yes — current year','Yes — prior years','Not sure']],['select','Financial or tax filings affected?','filings_affected',['No','Yes','Possibly / not sure']],['text','Required completion date','cleanup_deadline','Example: December 15 or before lender review']],result:['Accounting Cleanup & Stabilization','Your answers indicate a defined cleanup project should be scoped by historical period, affected accounts, payroll or filing impact, and the required completion date.']},
  controller:{match:'Fractional controller support',situationTitle:'Where is higher-level financial oversight most needed?',situationContext:'Choose the leadership gap you most need to solve.',situations:[['Month-end close lacks review or accountability','Close oversight','Reconciliations, adjustments, and financial statements need senior review.'],['Cash flow is difficult to forecast','Cash-flow visibility','The business needs better short-term and long-term liquidity planning.'],['Owners need better reporting and KPIs','Management reporting','Existing reports do not support operational decisions.'],['The business is growing beyond its current finance process','Finance function needs structure','Controls, procedures, staff review, and reporting need to scale.']],scopeTitle:'Define the controller and advisory requirements.',scopeContext:'Identify the reporting complexity, cadence, and decision-support needs.',fields:[['select','Approximate annual revenue','annual_revenue',['Under $1 million','$1–5 million','$5–15 million','$15–50 million','More than $50 million','Prefer not to say']],['select','Primary controller deliverable','controller_deliverable',['Close and balance-sheet review','Cash-flow forecasting','KPI and management reporting','Budgeting and variance analysis','Controls and staff oversight','Several of these']],['select','Reporting cadence','reporting_cadence',['Weekly','Monthly','Quarterly','Project-based']],['select','External reporting required?','external_reporting',['No','Lender or investor','Board or ownership group','Auditor or regulator','Several audiences']],['select','Internal accounting staff?','accounting_staff',['No internal staff','1 person','2–5 people','More than 5 people']]],result:['Fractional Controller Support','Your answers indicate a controller engagement should be designed around close oversight, reporting cadence, cash visibility, external reporting, and the support required by your internal team.']},
  systems:{match:'QuickBooks or systems implementation',situationTitle:'What type of accounting-systems project are you planning?',situationContext:'Choose the project that most closely matches your goal.',situations:[['I am implementing a new accounting or ERP system','New implementation','A new financial platform needs configuration, mapping, testing, and training.'],['I am converting from one system to another','System conversion','Historical data and balances must move into a replacement platform.'],['My accounting, payroll, banking, or operating systems do not connect','Integration problem','Mappings, imports, feeds, or duplicate processes need correction.'],['The existing system works, but the workflow is inefficient','Workflow redesign','Processes, controls, documentation, and responsibilities need improvement.']],scopeTitle:'Define the implementation and integration project.',scopeContext:'Identify the platforms, data history, integrations, users, and desired launch date.',fields:[['text','Current accounting or ERP system','current_platform','QuickBooks, SAP, Oracle, Dynamics, spreadsheet, or other'],['text','Target system or project goal','target_platform','New platform, conversion, integration, or redesigned workflow'],['select','Historical data to migrate','migration_history',['Opening balances only','Current year','1–2 prior years','More than 2 years','Not sure']],['text','Systems that must connect','integrations','Payroll, banking, merchant, TMS, CRM, reporting, or other'],['text','Desired go-live date','go_live','Example: January 1 or within 60 days']],result:['Accounting Systems & Workflow Project','Your answers indicate a systems project should be scoped around the current and target platforms, migration history, required integrations, workflow design, testing, and go-live timing.']},
  payroll:{match:'Payroll processing and integration',situationTitle:'What payroll problem or need should be addressed?',situationContext:'Choose the payroll situation that best describes your business.',situations:[['I need recurring payroll processing','Ongoing payroll processing','Regular payroll runs, reporting, liabilities, and accounting integration are needed.'],['I am changing or implementing a payroll provider','Payroll setup or conversion','Employees, deductions, taxes, balances, and workflows must be configured.'],['Payroll liabilities or general-ledger entries do not reconcile','Payroll reconciliation issue','Payroll reports, tax accounts, and accounting balances do not agree.'],['I have multi-state or complex payroll requirements','Multi-state or complex payroll','Employees, contractors, jurisdictions, or deductions add complexity.']],scopeTitle:'Define the payroll-processing requirements.',scopeContext:'Identify workforce size, jurisdictions, frequency, provider, and the next required payroll date.',fields:[['select','Employees and contractors','worker_count',['1–10','11–25','26–50','51–100','More than 100']],['select','States with workers','payroll_states',['1 state','2–3 states','4–10 states','More than 10 states','Not sure']],['select','Payroll frequency','payroll_frequency',['Weekly','Biweekly','Semimonthly','Monthly','Multiple frequencies']],['text','Current payroll provider','payroll_provider','ADP, Gusto, Paycor, Workday, Thomson Reuters, or other'],['text','Next payroll or target start date','next_payroll','Example: October 30 or next quarter']],result:['Payroll Processing & Integration Review','Your answers indicate payroll support should be scoped around workforce size, state jurisdictions, pay frequency, provider setup, liability reconciliation, and payroll-to-ledger integration.']},
  transportation:{match:'Transportation accounting and reporting',situationTitle:'Which transportation accounting or reporting area needs attention?',situationContext:'Choose the most urgent operating or compliance need.',situations:[['I need ongoing transportation accounting','Full transportation accounting','Settlements, expenses, reconciliations, profitability, and reporting need ongoing support.'],['Federal or state reports are due or behind','Reporting or filing deadline','IFTA, IRP, UCR, Form 2290, KYU, or state mileage reports need attention.'],['TMS, fuel, settlements, and accounting records do not match','Systems and reconciliation issue','Operational and financial data require integration and reconciliation.'],['I need better equipment, lane, or driver profitability','Profitability visibility','The business needs decision-ready operating and financial reports.']],scopeTitle:'Define the transportation-company requirements.',scopeContext:'Identify operation type, fleet size, jurisdictions, reporting obligations, and operating systems.',fields:[['select','Operation type','transport_operation',['Motor carrier','Freight broker','Carrier and broker','Owner-operator fleet','Other transportation operation']],['select','Fleet or operating size','fleet_size',['1–5 units','6–20 units','21–50 units','More than 50 units','Non-asset operation']],['select','States or jurisdictions operated in','operating_states',['1–3','4–10','11–25','More than 25','Interstate / nationwide']],['select','Primary reporting requirement','transport_reporting',['IFTA and fuel tax','IRP, UCR, or Form 2290','KYU or other state mileage reporting','Settlements and TMS reconciliation','Full accounting and reporting support']],['text','TMS, ELD, fuel-card, or dispatch systems','transport_systems','AscendTMS, Prophesy, Tailwind, Samsara, fuel card, or other']],result:['Transportation Accounting & Reporting Assessment','Your answers indicate a transportation engagement should be scoped around operation type, fleet size, operating jurisdictions, federal and state reporting, settlements, TMS data, and profitability reporting.']},
  realestate:{match:'Real estate accounting',situationTitle:'What type of real estate accounting support do you need?',situationContext:'Choose the situation that best describes the property portfolio or project.',situations:[['I need ongoing accounting for rental properties','Recurring property accounting','Monthly transaction review, reconciliations, property reporting, and close support are needed.'],['My property or entity books need cleanup','Real estate cleanup','Historical rent, expenses, loans, escrow, security deposits, or intercompany activity need correction.'],['I need reporting by property, entity, or owner','Property and ownership reporting','Financial results need to be separated and consolidated across properties or entities.'],['I need acquisition, renovation, or development cost tracking','Project and job-cost accounting','Purchase, construction, renovation, draw, and carrying costs need organized tracking.']],scopeTitle:'Define the real estate accounting portfolio.',scopeContext:'Identify the property type, portfolio size, ownership structure, systems, and most important reporting requirement.',fields:[['select','Property or portfolio type','property_type',['Single-family rentals','Multifamily residential','Commercial real estate','Mixed-use properties','Short-term rentals','Development or renovation projects','Multiple property types']],['select','Properties or active projects','property_count',['1–3','4–10','11–25','26–50','More than 50']],['select','Rental units, if applicable','unit_count',['1–10','11–50','51–150','More than 150','Not applicable / not sure']],['select','Ownership entities or company files','real_estate_entities',['1','2–5','6–15','More than 15','Not sure']],['text','Accounting or property-management systems','property_systems','QuickBooks, AppFolio, Buildium, Rent Manager, Yardi, spreadsheet, or other'],['select','Primary accounting priority','property_priority',['Monthly property-level reporting','Rent and tenant-charge reconciliation','Security deposits, escrow, and loans','CAM or operating-expense tracking','Acquisition, renovation, or job costing','Cleanup and catch-up','Full portfolio accounting support']]],result:['Real Estate Accounting Assessment','Your answers indicate a property-specific engagement should be scoped around portfolio type, unit and entity count, rent and deposit workflows, debt and escrow activity, property-management systems, and required owner or investor reporting.']},
  leaseabstraction:{match:'Commercial lease abstraction',situationTitle:'What is driving the lease-abstraction project?',situationContext:'Choose the business event or portfolio need that best describes the assignment.',situations:[['New or acquired leases need standardized summaries','New portfolio or lease onboarding','Lease documents need consistent abstracts for accounting and property operations.'],['Renewals, options, or critical dates need review','Critical-date management','Upcoming notices, expirations, renewals, options, and escalations need to be identified.'],['A transaction, audit, or due-diligence review is underway','Due diligence or transaction support','Key financial and operating terms must be extracted for review and decision-making.'],['Lease data must be migrated into an accounting or property system','System migration or data standardization','Existing documents and schedules need structured, validated fields for import or ongoing administration.'],['Rent, CAM, or lease obligations need reconciliation','Lease-accounting support','Contract terms need to be compared with billing, payment schedules, or operating-expense treatment.']],scopeTitle:'Define the commercial lease-abstraction assignment.',scopeContext:'Identify the document volume, property and lease types, locations, required data fields, source condition, and delivery deadline.',fields:[['select','Leases requiring abstraction','lease_count',['1–5','6–20','21–50','51–100','More than 100','Not sure']],['select','Lease position','lease_position',['Tenant / lessee','Landlord / lessor','Both','Property manager or advisor','Not sure']],['select','Property or lease type','lease_property_type',['Office','Retail','Industrial or warehouse','Medical','Mixed-use','Ground lease','Multiple property types','Other']],['text','States or markets covered','lease_markets','List the states, cities, or portfolio markets'],['select','Source-document condition','lease_document_condition',['Executed leases only','Leases plus amendments or addenda','Scanned or mixed-format files','Documents require organization first','Not sure']],['select','Required abstraction detail','lease_detail',['Core financial and date terms','Full lease abstract','Custom client template','System-import-ready data','Not sure — recommend a format']],['text','Required fields or destination system','lease_output','Examples: rent steps, options, CAM, insurance, obligations, Yardi, MRI, Excel'],['text','Required completion date','lease_deadline','Example: before acquisition close, renewal review, audit, or system migration']],result:['Commercial Lease Abstraction Review','Your answers indicate a lease-abstraction project should be scoped around document volume, lease position, property type, amendments, required financial and legal-business fields, output format, quality review, and delivery deadline.']},
  energy:{match:'Energy cost management and commercial energy brokerage',situationTitle:'What is prompting the commercial energy review?',situationContext:'Choose the situation that best matches your electric or natural-gas needs.',situations:[['My supply contract is expiring or renewing','Contract renewal','Current terms, renewal timing, and competitive supplier options need review.'],['Energy costs have increased or become unpredictable','Cost increase or volatility','Pricing, usage, and budget impact need analysis.'],['I manage multiple locations or utility accounts','Multi-location energy management','Accounts, suppliers, contract dates, and costs need coordination.'],['I want to compare suppliers and purchasing strategies','Supplier and strategy review','Available options, contract structures, and market timing need evaluation.']],scopeTitle:'Define the commercial energy-procurement scope.',scopeContext:'Identify the commodity, account footprint, market locations, contract status, and current cost level.',fields:[['select','Energy service','energy_service',['Electric','Natural gas','Electric and natural gas','Not sure']],['select','Commercial utility accounts','utility_accounts',['1','2–5','6–15','More than 15','Not sure']],['text','States and utility territories','utility_markets','Example: Ohio — FirstEnergy and Columbia Gas'],['select','Current contract status','contract_status',['Under contract — renewal within 6 months','Under contract — renewal more than 6 months away','Month-to-month or variable','No competitive supplier','Not sure']],['select','Approximate monthly energy spend','energy_spend',['Under $2,500','$2,500–$10,000','$10,001–$50,000','More than $50,000','Prefer not to say']]],result:['Commercial Energy Cost Review','Your answers indicate an energy review should evaluate commodity type, account footprint, utility territory, current contract status, supplier options, renewal timing, and budget impact.']}
};

const form=document.getElementById('consultation-form');
if(form){
  const steps=[...form.querySelectorAll('.form-step')];
  const next=document.getElementById('next-step');
  const back=document.getElementById('back-step');
  const count=document.getElementById('step-count');
  const bar=document.getElementById('progress-bar');
  const controls=form.querySelector('.form-controls');
  const result=document.getElementById('assessment-result');
  const conditionOptions=document.getElementById('condition-options');
  const dynamicScope=document.getElementById('dynamic-scope-fields');
  let current=0;
  let activeKey='';

  const selectedService=()=>String(new FormData(form).get('service')||'');
  const selectedConfig=()=>Object.entries(assessment).find(([,config])=>config.match===selectedService())||[];
  const consultationInbox={
    'Transportation accounting and reporting':'transportation@claritygridaccounting.com',
    'Real estate accounting':'realestate@claritygridaccounting.com',
    'Commercial lease abstraction':'realestate@claritygridaccounting.com'
  };
  const consultationDestination=service=>consultationInbox[service]||'consultations@claritygridaccounting.com';
  const escapeHtml=value=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));

  const renderBranch=()=>{
    const [key,config]=selectedConfig();
    if(!config||key===activeKey)return;
    activeKey=key;
    document.getElementById('situation-title').textContent=config.situationTitle;
    document.getElementById('situation-context').textContent=config.situationContext;
    conditionOptions.innerHTML=config.situations.map((item,index)=>`<label class="choice"><input type="radio" name="condition" value="${escapeHtml(item[0])}" ${index===0?'required':''}><span><strong>${escapeHtml(item[1])}</strong><small>${escapeHtml(item[2])}</small></span></label>`).join('');
    document.getElementById('scope-title').textContent=config.scopeTitle;
    document.getElementById('scope-context').textContent=config.scopeContext;
    dynamicScope.innerHTML=`<p class="scope-heading">Service-specific details</p><div class="dynamic-field-grid">${config.fields.map(field=>{const [type,label,name,options]=field;if(type==='select')return `<label>${escapeHtml(label)}<select name="${escapeHtml(name)}" data-scope-input data-label="${escapeHtml(label)}" required><option value="">Select an option</option>${options.map(option=>`<option>${escapeHtml(option)}</option>`).join('')}</select></label>`;return `<label>${escapeHtml(label)}<input type="text" name="${escapeHtml(name)}" data-scope-input data-label="${escapeHtml(label)}" required placeholder="${escapeHtml(options)}"></label>`;}).join('')}</div>`;
  };

  const showStep=()=>{
    if(current>0)renderBranch();
    steps.forEach((step,index)=>step.classList.toggle('active',index===current));
    count.textContent=`Step ${current+1} of ${steps.length}`;
    bar.style.width=`${((current+1)/steps.length)*100}%`;
    back.hidden=current===0;
    next.innerHTML=current===steps.length-1?'See my recommendation <span>→</span>':'Continue <span>→</span>';
  };

  const validateStep=()=>{for(const field of steps[current].querySelectorAll('input,select,textarea')){if(!field.checkValidity()){field.reportValidity();return false;}}return true;};

  next.addEventListener('click',()=>{
    if(!validateStep())return;
    if(current<steps.length-1){current++;showStep();steps[current].querySelector('input,select,textarea')?.focus();return;}
    const [,config]=selectedConfig();
    document.getElementById('result-title').textContent=config?.result[0]||selectedService();
    document.getElementById('result-copy').textContent=config?.result[1]||'A focused discovery call will confirm scope, timing, systems, and the most practical engagement structure.';
    const submitButton=result.querySelector('button[type="submit"]');
    const resultSteps=result.querySelector('ol');
    const resultNote=result.querySelector('.form-note');
    if(activeKey==='energy'){
      submitButton.type='button';
      submitButton.innerHTML='Complete secure energy quote packet <span>↗</span>';
      submitButton.onclick=()=>window.open('https://form.jotform.com/262890751156059','_blank','noopener');
      resultSteps.innerHTML='<li>Open the secure commercial-energy intake.</li><li>Complete business, service, supplier, and timing details.</li><li>Upload electric and natural-gas bills in their separately labeled fields.</li>';
      resultNote.textContent='Utility bills are collected through the secure quote form, not email. Uploading documents does not enroll your business with a supplier.';
    }else{
      submitButton.type='submit';
      submitButton.innerHTML='Send my consultation request <span>↗</span>';
      submitButton.onclick=null;
      resultSteps.innerHTML='<li>Review the prepared request.</li><li>Send it from your email application.</li><li>Devon will follow up to confirm fit and consultation timing.</li>';
      resultNote.textContent='Your request is routed to the ClarityGrid inbox assigned to the service you selected. Do not include passwords, bank credentials, Social Security numbers, or sensitive documents by email.';
    }
    steps[current].classList.remove('active');controls.hidden=true;count.textContent='Assessment complete';bar.style.width='100%';result.hidden=false;result.focus();
  });

  back.addEventListener('click',()=>{if(current>0){current--;showStep();}});

  form.addEventListener('change',event=>{if(event.target.name==='service'&&current===0)activeKey='';});

  document.querySelectorAll('[data-service-select]').forEach(link=>link.addEventListener('click',()=>{
    const option=form.querySelector(`input[name="service"][value="${CSS.escape(link.dataset.serviceSelect)}"]`);
    if(option){option.checked=true;activeKey='';current=0;result.hidden=true;controls.hidden=false;showStep();}
  }));

  form.addEventListener('submit',event=>{
    event.preventDefault();
    const data=new FormData(form);const service=data.get('service');
    const scopeLines=[...form.querySelectorAll('[data-scope-input]')].map(field=>field.dataset.label+': '+(field.value||'Not provided')).join('\n');
    const subject=encodeURIComponent('Qualified consultation request — '+service);
    const body=encodeURIComponent('Hello Devon,\n\nI completed the ClarityGrid website assessment and would like to request a consultation.\n\nName: '+data.get('name')+'\nCompany: '+(data.get('company')||'Not provided')+'\nEmail: '+data.get('email')+'\nPhone: '+(data.get('phone')||'Not provided')+'\n\nPrimary need: '+service+'\nService-specific situation: '+data.get('condition')+'\nTiming: '+data.get('urgency')+'\nBusiness locations: '+data.get('locations')+'\n\nService scope:\n'+scopeLines+'\n\nAdditional details:\n'+(data.get('message')||'None provided')+'\n\nThank you.');
    window.location.href='mailto:'+consultationDestination(String(service))+'?subject='+subject+'&body='+body;
  });

  showStep();
}
